import test from 'node:test';
import assert from 'node:assert/strict';
import { normalizeId, mergeCustomers } from '../src/customers.js';

test('normalizeId trims and uppercases', () => {
  assert.equal(normalizeId('c-001'), 'C-001');
  assert.equal(normalizeId(' C-002 '), 'C-002');
  assert.equal(normalizeId('c-003'), 'C-003');
});

test('mergeCustomers removes fromId customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
    { id: 'C-003', name: 'Customer 3' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, 2);
  assert.equal(r.value.customers.find((c) => c.id === 'C-001'), undefined);
});

test('mergeCustomers transfers invoices from fromId to intoId', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
  ];
  const invoices = [
    { number: 'INV-001', customerId: 'C-001' },
    { number: 'INV-002', customerId: 'C-002' },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 2);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
  assert.equal(r.value.invoices[1].customerId, 'C-002');
});

test('mergeCustomers preserves invoices from other customers', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
    { id: 'C-003', name: 'Customer 3' },
  ];
  const invoices = [
    { number: 'INV-001', customerId: 'C-001' },
    { number: 'INV-002', customerId: 'C-002' },
    { number: 'INV-003', customerId: 'C-003' },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  const c3Invoices = r.value.invoices.filter((inv) => inv.customerId === 'C-003');
  assert.equal(c3Invoices.length, 1);
  assert.equal(c3Invoices[0].number, 'INV-003');
});

test('mergeCustomers rejects if fromId does not exist', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-999', 'C-002');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers rejects if intoId does not exist', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-999');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers rejects if same customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-001');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'SAME_CUSTOMER');
});

test('mergeCustomers normalizes IDs (case insensitive)', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
  ];
  const invoices = [
    { number: 'INV-001', customerId: 'C-001' },
  ];

  const r = mergeCustomers(customers, invoices, 'c-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers normalizes IDs with whitespace', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
  ];
  const invoices = [
    { number: 'INV-001', customerId: 'C-001' },
  ];

  const r = mergeCustomers(customers, invoices, ' C-001 ', ' C-002 ');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers does not mutate input customers', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
  ];
  const originalCopy = JSON.parse(JSON.stringify(customers));
  const invoices = [];

  mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.deepEqual(customers, originalCopy);
});

test('mergeCustomers does not mutate input invoices', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
  ];
  const invoices = [
    { number: 'INV-001', customerId: 'C-001' },
  ];
  const originalCopy = JSON.parse(JSON.stringify(invoices));

  mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.deepEqual(invoices, originalCopy);
});

test('mergeCustomers with multiple invoices from fromId', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
  ];
  const invoices = [
    { number: 'INV-001', customerId: 'C-001' },
    { number: 'INV-002', customerId: 'C-001' },
    { number: 'INV-003', customerId: 'C-001' },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  const c2Invoices = r.value.invoices.filter((inv) => inv.customerId === 'C-002');
  assert.equal(c2Invoices.length, 3);
});

test('mergeCustomers preserves other invoice fields', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
  ];
  const invoices = [
    { number: 'INV-001', customerId: 'C-001', status: 'issued', total: 10000 },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].number, 'INV-001');
  assert.equal(r.value.invoices[0].status, 'issued');
  assert.equal(r.value.invoices[0].total, 10000);
});

test('mergeCustomers with empty invoices array', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1' },
    { id: 'C-002', name: 'Customer 2' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
  assert.equal(r.value.customers.length, 1);
});

test('mergeCustomers maintains customer data integrity', () => {
  const customers = [
    { id: 'C-001', name: 'Customer 1', email: 'c1@example.com' },
    { id: 'C-002', name: 'Customer 2', email: 'c2@example.com' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  const c2 = r.value.customers.find((c) => c.id === 'C-002');
  assert.equal(c2.name, 'Customer 2');
  assert.equal(c2.email, 'c2@example.com');
});

